public static IEnumerable<long> Fibonacci()
{
    long a = 0, b = 1;
    while (true)
    {
        yield return a;              // produced on demand
        (a, b) = (b, a + b);
    }
}
foreach (var n in Fibonacci().Take(10)) Console.WriteLine(n);

