public static async IAsyncEnumerable<string> Tail(
    string path, [EnumeratorCancellation] CancellationToken ct = default)
{
    using var reader = new StreamReader(path);
    while (await reader.ReadLineAsync(ct) is { } line)
        yield return line;           // one line per awaited pull
}

await foreach (var line in Tail("app.log").WithCancellation(ct))
    if (line.Contains("ERROR")) break;   // disposal runs the async cleanup
